        );

        // 鎵嬪姩娉ㄥ唽 Harmony Patch
        var harmony = new Harmony("HSG.HelpPatch");

        // Patch GetTabsWidget 鏂规硶
        var getTabsWidgetMethod = typeof(HelpScreen).GetMethod(
            "GetTabsWidget",
