            {
                _cachedOpenAssignableHelpMethod.Invoke(null, new object[] { assignable });
            }
        }
        catch (Exception ex)
        {
            HsgDebug.LogError($"[HelpPatch] OpenAssignableHelpCustom 澶辫触: {ex.Message}");
