        );
    Miraclist() : base("miraclist", Cor.lightYellow, RoleCategory.CrewmateRole, NebulaTeams.CrewmateTeam, 
        [FateWeaveCanSelectRoles,
        //HasChatChannel,
        WillPublicRole,
        CanBeGuessedAfterPublicRole,
        HowToKnowDSDie,
