    {
        string exceptionName = (e.ExceptionObject as Exception)?.GetType().Name ?? "UnknownException";
        string logLine = $"Error<{DateTime.Now:HH:mm:ss}>: {exceptionName}";
        AppendLog(logLine);
    }
    static void AppendLog(string content)
    {
        try
